head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function(e) {
    try {
        // 초기화함수
        scwin.init();

        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92011.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    ibx_instNm.focus();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ibx_coSnm_onkeydown
 * @description ibx_coSnm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ibx_coSnm_onkeydown = function(e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92011.ibx_coSnm_onkeydown" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Search_onclick = function (e) {
    try {
        // 조회 버튼 클릭
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92011.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description img_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92011.img_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_Search_onkeydown = function (e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92011.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name grd_IsuInst_oncelldblclick
 * @description grd_IsuInst 셀 더블클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.setParam(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92011.grd_IsuInst_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 기업목록 조회
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    // 데이터셋 초기화
    scwin.initDs();
    let sbmOptions = {};
    let actionUrl = "";

    dma_searchReq.set("instNm", ibx_instNm.getValue());

    actionUrl = "/api/listing/common/pop/inst/select-list";

    sbmOptions = {
            id: "sbm_isuList",
            action: actionUrl,
            method: "get",
            ref: "dma_searchReq",
            target: "dlt_listRes=body",
            gridview: "grd_list",
            submitDoneHandler: scwin.sbm_Detail_submitdone
    };

    $c.sbm.executeDynamic(sbmOptions);

};

/**
 * @method
 * @name sbm_Detail_submitdone
 * @description Detail 통신 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_Detail_submitdone = function (e) {
    // dlt_listRes.setJSON(e.responseJSON.body);
    txb_TotCnt.setValue(dlt_listRes.getRowCount());
};

/**
 * @method
 * @name sbm_isurList_submitdone
 * @description isurList 통신 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_isurList_submitdone = function (e) {
    dlt_listRes.setJSON(e.responseJSON.body);
    txb_TotCnt.setValue(dlt_listRes.getRowCount());
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dlt_listRes.removeAll();
    txb_TotCnt.setValue("0");
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function(v_Currow) {

    if (v_Currow === undefined) {
        v_Currow = dlt_listRes.getRowPosition();
    }
    const res = dlt_listRes.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};
